import{_ as s,c as i,o as t,aj as a}from"./chunks/framework.BlveriQe.js";const g=JSON.parse('{"title":"Configuring Primitive Services","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/configuring-primitive-services.md","filePath":"getting-started/configuring-primitive-services.md"}'),n={name:"getting-started/configuring-primitive-services.md"};function o(r,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="configuring-primitive-services" tabindex="-1">Configuring Primitive Services <a class="header-anchor" href="#configuring-primitive-services" aria-label="Permalink to “Configuring Primitive Services”">​</a></h1><p>Everything Primitive does for your app — which sign-in methods are enabled, what workflows exist, which external APIs can be called, what database operations clients may run — is <strong>configuration of Primitive&#39;s services, stored on the Primitive servers</strong>. Your client code doesn&#39;t define that behavior; it invokes what configuration declares.</p><p>There are two equivalent ways to manage that configuration:</p><ol><li><strong>The <a href="https://admin.primitiveapi.com" target="_blank" rel="noreferrer">Admin Console</a></strong> — interactive and visual. Best for exploring, testing, and one-off changes.</li><li><strong>TOML files in your repo, synced via the CLI</strong> — configuration as code. Best for anything you want versioned, reviewed, reproduced across environments, or managed by an AI coding agent.</li></ol><p>Both edit the same underlying configuration. Most teams explore in the console and commit the result as TOML.</p><h2 id="the-sync-loop" tabindex="-1">The Sync Loop <a class="header-anchor" href="#the-sync-loop" aria-label="Permalink to “The Sync Loop”">​</a></h2><p><code>primitive config</code> round-trips your app&#39;s configuration between the server and a directory of TOML files:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # create the directory structure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # download current server config as TOML</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... edit files locally ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # see what would change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # apply your changes to the server</span></span></code></pre></div><p>The config directory auto-resolves to <code>.primitive/sync/&lt;env&gt;/&lt;appId&gt;/</code> — one isolated slot per environment. Pass <code>--dir &lt;path&gt;</code> to override it with a fixed directory.</p><p>The files live in your repo, so configuration changes ride the same workflow as code: branches, diffs, reviews, rollbacks. <code>config push</code> validates every file before applying anything — a validation error aborts the push with no changes applied — and reports the file and entity behind any failure.</p><p><strong>Preview before you push.</strong> <code>primitive config diff</code> shows which entities would be created, changed, or removed; <code>primitive config push --dry-run</code> walks the full push and reports the same outcome without writing anything. A local file with no matching server entity falls into one of two groups, reported separately: a file you authored and never pulled is <strong>new</strong> — push will create it — while a file a prior pull wrote whose entity is now absent from the server was deleted server-side, so push would <strong>re-create</strong> it unless you remove the file. <code>diff</code> compares every resource type <code>config push</code> handles — workflows, transforms, prompts, email templates, webhooks, database types, rule sets, group- and collection-type configs, and metadata-category configs are compared for content, not just presence, so an edit that changes only a field (a prompt&#39;s <code>accessRule</code>, a webhook&#39;s <code>workflowKey</code>) is reported as <strong>Modified</strong> rather than reading as in sync, alongside integrations, cron triggers, blob buckets, and the rest. If it can&#39;t fetch a type&#39;s current state from the server, that type is named explicitly under a <strong>not compared</strong> line instead of being silently left out, so the summary is never mistaken for exhaustive. One caveat: <code>diff</code> counts entities only, so a change confined to <code>app.toml</code> (app settings) shows up as all-zero counts there — preview app-settings changes with <code>push --dry-run</code>, which includes them. Both run the identical validation a real push runs, so a rejection — an operation whose database type has no schema, an unresolved reference, a schema change that would break an existing operation — surfaces in the preview exactly as it would on push. The preview is faithful: what it reports is what <code>config push</code> will do. And a blocked entity records no sync state, so it stays visible as pending on the next <code>diff</code> instead of quietly reading as &quot;in sync.&quot;</p><p><strong>Removing a managed field clears it.</strong> For the fields the CLI owns on a synced entity, the local file is the source of truth: delete a line and the next <code>push</code> clears that field on the server rather than leaving the old value in place. Remove a database type&#39;s <code>ruleSetName</code> or <code>celContextAccess</code>, or an integration, webhook, or prompt&#39;s <code>description</code>, and push sets it back to empty — for database types it reports each one as <code>Cleared &lt;field&gt; on &lt;type&gt;</code>. Workflows are the strongest form of this rule: push sends the entire <code>[workflow]</code> table, so a removed line is cleared (<code>description</code>, <code>accessRule</code>, <code>runAs</code>, <code>capabilities</code>, the schemas, <code>[workflow.lock]</code>, <code>syncCallable</code>) or <strong>reset to its default</strong> (<code>status</code>, the queue limits, <code>dequeueOrder</code>, <code>requiresClientApply</code>) — defaulted fields included, unlike elsewhere. See <a href="./workflows.html#syncing-workflow-config">Syncing Workflow Config</a> for the values. This is field-level and separate from removing a whole file: a default push never deletes an entity, so a file you delete simply isn&#39;t pushed and its server entity stays put (tree-level deletions are handled by the pull-side reconciliation and <code>push --prune</code> below). App settings in <code>app.toml</code> are the deliberate exception in the other direction — there an omitted key preserves the server value (see <a href="#what-lives-in-the-config-directory">What Lives in the Config Directory</a>).</p><p><strong>An unrecognized key is an error, not a shrug.</strong> <code>config push</code> rejects any key the CLI does not recognize — in a workflow&#39;s <code>[workflow]</code> table, a prompt&#39;s <code>[prompt]</code> or <code>[[configs]]</code> blocks, or an integration, webhook, cron trigger, blob bucket, email template, database type, rule set, group- or collection-type config or metadata-category config&#39;s table, in <code>app.toml</code>&#39;s <code>[app]</code> / <code>[auth]</code> / <code>[cors]</code> / <code>[invitations]</code> sections, and in a <code>&lt;key&gt;.tests/</code> test-case file&#39;s <code>[test]</code> table — naming the file and the key, so a typo fails locally instead of being silently dropped on the way to the server. The same goes for a whole table: a mistyped header (<code>[integraton]</code>) or a repeated table written with single brackets (<code>[configs]</code> where <code>[[configs]]</code> is meant) is named too, because the file would otherwise push as though the table it meant to write were empty — clearing the fields inside it. The check runs in pre-flight, so a bad key or table aborts before anything is applied. The mirror case is a CLI older than the server: <code>config pull</code> names every key the server returned that this CLI version does not know and leaves it out of the file rather than writing a key the next push would reject. Nothing is dropped without a message, and the round trip stays safe — push only sends the fields it knows, so the server keeps its stored values for the rest. Upgrade the CLI (<code>npm i -g primitive-admin@latest</code>) to manage the new keys.</p><p><strong>Structured values are native TOML tables.</strong> Where a config surface takes a structured value — an operation&#39;s <code>definition</code> and <code>params</code>, a subscription&#39;s <code>params</code>, a workflow step&#39;s object fields — the file writes nested TOML tables. A file may instead hold those values as single-line JSON strings (the older encoding); the server treats the two identically, <code>config pull</code> keeps whichever form a file already uses, and <code>primitive config migrate-toml</code> rewrites a file from JSON strings to TOML tables in place.</p><p><strong><code>config pull</code> mirrors deletions.</strong> A pull doesn&#39;t only write files — after downloading the current configuration it also removes local files whose entity a prior pull wrote but the server no longer returns (an entity you deleted in the console or with a delete command). This keeps the config directory a faithful mirror: because a default <code>config push</code> treats every local TOML as something to create or update, a stale file left behind would re-create the entity you just deleted. Files you authored by hand and never pulled are left untouched — a <code>diff</code> lists them as <em>new</em> — and a file with uncommitted git changes is kept rather than removed, so an in-progress edit is never lost. Pass <code>--no-prune</code> to keep every local file regardless; and because the snapshot below is taken first, <code>config revert</code> restores anything a pull removed unexpectedly.</p><p><strong><code>config push --prune</code> mirrors deletions the other way.</strong> By default a push only creates and updates — delete a local file and its server entity lives on. Pass <code>--prune</code> and push also deletes: after the create/update pass, it removes managed entities — the ones a prior pull recorded in sync state — whose local TOML you&#39;ve since deleted. Entities authored in the console and never pulled are never touched. <code>config diff</code> shows every server entity that has no local file under <strong>Remote only</strong>, split into <em>managed</em> (which <code>--prune</code> deletes) and <em>unmanaged</em> (left alone). Each deletion is confirmed by a fresh read of the entity and skipped if it changed on the server since your last sync — <code>--force</code> overrides that check — and an entity still referenced by another is reported and kept while the rest proceed. Push confirms once before deleting; <code>--yes</code> skips the prompt for CI, and <code>--dry-run</code> reports the plan without deleting anything. Webhooks are the one exception to what &quot;deletes&quot; means here: a pruned webhook is <strong>permanently deleted</strong>, not archived — see <a href="./inbound-webhooks.html#limits-archiving-and-deletion">Inbound Webhooks</a>.</p><p>Every <code>config pull</code> snapshots the config directory before writing, so a pull that overwrites local edits is recoverable:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # list available snapshots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # restore the most recent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --snapshot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # restore a specific one</span></span></code></pre></div><p>Snapshots are local CLI state, kept out of version control and pruned after 28 days. <code>revert</code> replaces the config directory with the snapshot — run <code>primitive config diff</code> afterwards to see where the restored files stand relative to the server.</p><p><strong>Make the sync tree the single source of truth.</strong> Once you manage configuration as TOML, create entities and land changes by editing files and pushing — including throwaway test or debugging workflows — rather than with console edits. The CLI records each pushed entity&#39;s server identity in <code>.primitive-sync.json</code>, a state file in the config directory, and uses it to decide whether a push creates or updates each entity; changes made outside the loop leave that state out of date, and the two directions behave differently. For an entity <strong>created</strong> outside the loop (a console edit), push adopts by key: a create that hits a conflict matches the existing entity and updates it in place instead of failing, so re-running a push that hit a conflict succeeds. An entity <strong>deleted</strong> outside the loop leaves a stale entry behind: the next push of an edited version of its TOML updates an entity that no longer exists and fails with a &quot;not found&quot; error. When a push fails that way, remove that entity&#39;s entry from <code>.primitive-sync.json</code> and push again — the entity is created fresh.</p><h2 id="toml-is-the-only-write-path" tabindex="-1">TOML Is the Only Write Path <a class="header-anchor" href="#toml-is-the-only-write-path" aria-label="Permalink to “TOML Is the Only Write Path”">​</a></h2><p>Server-side configuration is authored in TOML and applied with <code>primitive config push</code>. That is the only way the CLI writes it: there are no <code>primitive &lt;thing&gt; create</code> / <code>update</code> / <code>delete</code> commands and no flags that set a configuration field. Whatever you want to change — a workflow&#39;s steps, an integration&#39;s base URL, a prompt&#39;s model config, a cron schedule, an app setting, a config var — you edit the file that owns it and push.</p><p>Four commands cover authoring without leaving the terminal:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fields</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # the type&#39;s TOML keys, types, required, defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-intake</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # scaffold workflows/order-intake.toml from defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow/order-intake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow.status=active</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # edit one scalar in place</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow/order-intake</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # apply just that object</span></span></code></pre></div><ul><li><strong><code>config fields &lt;type&gt;</code></strong> lists a configuration type&#39;s TOML keys with their types, whether they&#39;re required, and their defaults — the way to discover the field surface. <code>--json</code> prints it for tooling, and <code>primitive config fields --help</code> lists every type it accepts.</li><li><strong><code>config create &lt;type&gt; &lt;key&gt;</code></strong> writes <code>&lt;key&gt;.toml</code> in that type&#39;s directory, filled in from the type&#39;s defaults. It is local only — nothing reaches the server until you push.</li><li><strong><code>config set &lt;object&gt; &lt;path&gt;=&lt;value&gt;...</code></strong> sets one or more scalars in an existing file, preserving comments and key order. <code>&lt;object&gt;</code> is <code>&lt;type&gt;/&lt;key&gt;</code>, <code>app</code>, or <code>vars</code>. Also local only. Tables and arrays are edited in the file directly.</li><li><strong><code>config push --only &lt;selector&gt;[,...]</code></strong> applies just the named objects instead of the whole tree. Selectors are <code>&lt;type&gt;/&lt;key&gt;</code>, <code>app</code>, or <code>var/&lt;key&gt;</code>. Everything else about push — validation, conflict detection, <code>--dry-run</code>, <code>--force</code>, <code>--prune</code> — behaves the same.</li></ul><p><code>set</code> plus <code>push --only</code> is the scripting path: two commands, no here-document, no temporary file.</p><p><strong>Deleting</strong> a configuration object means deleting its file and running <code>primitive config push --prune</code> — every type, no exceptions. One caveat is specific to metadata categories: deleting the definition does <strong>not</strong> delete stored metadata values, which become unreachable, so delete the values first (<code>primitive metadata delete</code>) if you need them gone. The prune plan says so before you confirm.</p><p><strong>What is not configuration stays interactive.</strong> Secrets (<code>primitive secrets set</code>) never go in a file. Resources whose creation mints a server id — <code>primitive apps create</code>, <code>databases create</code>, <code>collections create</code>, <code>groups create</code> — are created with a command, then configured in TOML. Data operations (<code>databases records</code>, <code>documents records</code>, <code>metadata set</code>) and every read or test command (<code>list</code>, <code>get</code>, <code>diff</code>, <code>test</code>, <code>execute</code>) are unaffected. Operational switches are runtime state, not configuration: <code>primitive workflows disable</code>/<code>enable</code> and <code>primitive cron-triggers pause</code>/<code>resume</code> write a runtime field that is deliberately not a TOML key, so a later <code>config push</code> cannot re-enable what an operator turned off — <code>config diff</code> reports it as &quot;operationally disabled; configuration unchanged&quot; rather than as drift.</p><h2 id="what-lives-in-the-config-directory" tabindex="-1">What Lives in the Config Directory <a class="header-anchor" href="#what-lives-in-the-config-directory" aria-label="Permalink to “What Lives in the Config Directory”">​</a></h2><p>One subdirectory per kind of configuration:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config/</span></span>
<span class="line"><span>  app.toml                        # App settings</span></span>
<span class="line"><span>  vars.toml                       # Config vars (non-secret key/value store)</span></span>
<span class="line"><span>  workflows/*.toml                # Workflow definitions</span></span>
<span class="line"><span>  workflows/{key}.configs/*.toml  # Named workflow config bodies</span></span>
<span class="line"><span>  workflows/{key}.tests/*.toml    # Workflow test cases</span></span>
<span class="line"><span>  workflow-fragments/*.toml       # Reusable step blocks</span></span>
<span class="line"><span>  transforms/*.rhai               # Rhai scripts for workflow script steps</span></span>
<span class="line"><span>  transforms/{name}.tests/*.toml  # Script test cases</span></span>
<span class="line"><span>  prompts/*.toml                  # Managed prompts</span></span>
<span class="line"><span>  prompts/{key}.tests/*.toml      # Prompt test cases</span></span>
<span class="line"><span>  integrations/*.toml             # External API integrations</span></span>
<span class="line"><span>  integrations/{key}.tests/*.toml # Integration test cases</span></span>
<span class="line"><span>  database-type-configs/*.toml           # Database operations, triggers, subscriptions</span></span>
<span class="line"><span>  webhooks/*.toml                 # Inbound webhooks</span></span>
<span class="line"><span>  cron-triggers/*.toml            # Scheduled workflow triggers</span></span>
<span class="line"><span>  blob-buckets/*.toml             # Blob bucket definitions</span></span>
<span class="line"><span>  email-templates/*.toml          # Email template overrides</span></span>
<span class="line"><span>  rule-sets/*.toml                # Access rule sets</span></span>
<span class="line"><span>  group-type-configs/*.toml       # Group type configuration</span></span>
<span class="line"><span>  collection-type-configs/*.toml  # Collection type configuration</span></span>
<span class="line"><span>  metadata-category-configs/*.toml # Resource metadata category configs</span></span></code></pre></div><p>Every feature page in these docs that shows a TOML block — <a href="./workflows.html">Workflows</a>, <a href="./prompts.html">Prompts</a>, <a href="./api-integrations.html">API Integrations</a>, <a href="./working-with-databases.html">Working with Databases</a>, <a href="./blobs-and-files.html">Blobs and Files</a>, <a href="./resource-metadata.html">Resource Metadata</a> — is describing one of these files. Define the entity in TOML, <code>primitive config push</code>, and it&#39;s live.</p><p><code>app.toml</code> holds the app-level settings. <code>primitive config push</code> applies them along with everything else, and <code>primitive config push --only app</code> applies just them. <code>primitive config pull --only app</code> writes the current server settings into <code>app.toml</code>, <code>primitive config diff --only app</code> shows per-field differences, and <code>primitive apps get</code> renders the current server-effective settings without touching any file. All of them read and write the same <code>app.toml</code>. The TOML-syncable settings are:</p><ul><li><code>[app]</code> — <code>name</code>, <code>mode</code>, <code>baseUrl</code>, <code>waitlistEnabled</code>, <code>waitlistNotifyAdmins</code>, <code>allowedDomains</code>, <code>testAccountBaseEmails</code></li><li><code>[auth]</code> — <code>googleOAuthEnabled</code>, <code>googleClientId</code>, <code>googleClientSecret</code>, <code>magicLinkEnabled</code>, <code>passkeyEnabled</code>, <code>appleSignInEnabled</code>, <code>appleAudiences</code>, <code>otpEnabled</code>, <code>redirectUris</code>, and <code>[auth.passkeys]</code> relying-party config</li><li><code>[cors]</code> — <code>mode</code>, <code>allowedOrigins</code>, <code>allowCredentials</code>, <code>allowedMethods</code>, <code>allowedHeaders</code>, <code>exposedHeaders</code>, <code>maxAge</code></li><li><code>[invitations]</code> — <code>enabled</code>, <code>limit</code> (whether members may send invitations and the per-member cap)</li></ul><p>Only the keys listed above are pushed — an omitted key leaves the server value untouched (it isn&#39;t cleared), and an unrecognized key (or a mistyped table header) is rejected by name before anything is applied, the same as for every other configuration file. This omit-preserves rule is specific to app settings; for a synced entity&#39;s own managed fields, removing the line clears the value (see <a href="#the-sync-loop">The Sync Loop</a>).</p><p><code>googleClientSecret</code> is a <code>{{secrets.KEY}}</code> reference, not the secret itself — store the value as an <a href="./app-secrets.html">app secret</a> first and point the setting at it. A literal value is rejected with <code>GOOGLE_CLIENT_SECRET_MUST_BE_SECRET_REF</code>, and a reference to a key that doesn&#39;t exist with <code>MISSING_GOOGLE_CLIENT_SECRET_REF</code>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GOOGLE_CLIENT_SECRET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">client-secre</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">googleClientId = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1234.apps.googleusercontent.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">googleClientSecret = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{secrets.GOOGLE_CLIENT_SECRET}}&quot;</span></span></code></pre></div><p>The server only sends this setting back when it holds a reference. An app configured before this rule shipped still holds the secret itself, which is never disclosed on read — the setting is absent from <code>app.toml</code> until you point it at a secret reference. <code>primitive apps get</code> and <code>primitive config pull</code> both print a warning naming the remediation, so a missing <code>googleClientSecret</code> is never silent.</p><p>Such a stored secret still works: Google sign-in on an app that never migrated keeps using it, so nothing breaks when this rule ships. It is deprecated, though, and it blocks configuration changes. While the stored value is a literal, <strong>any</strong> app-settings write — <code>primitive config push</code>, a console save — is rejected with <code>GOOGLE_CLIENT_SECRET_MIGRATION_REQUIRED</code> unless that same write migrates the field. Migrate it by storing the value as an app secret and setting <code>googleClientSecret</code> to the reference (or clear the setting to turn Google sign-in off):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GOOGLE_CLIENT_SECRET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">client-secre</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth.googleClientSecret=&#39;&quot;{{secrets.GOOGLE_CLIENT_SECRET}}&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span></span></code></pre></div><p><code>GOOGLE_OAUTH_MISCONFIGURED</code> is the code for a stored value that can&#39;t be resolved to a client secret. That covers a <em>reference</em> naming a secret which doesn&#39;t exist — for example one deleted after the setting was configured — and a value carrying reference syntax that no <code>{{secrets.KEY}}</code> reference accounts for (<code>{{secrets.foo}}</code>, <code>{secrets.KEY}</code>, or an otherwise-valid reference carrying an invisible character such as a zero-width space), reported on read as <code>googleClientSecretStatus = &quot;malformed-reference&quot;</code>. That second case is the one that is <strong>not</strong> still working: it is neither a pointer nor the secret Google issued, so it never reaches Google, and it is withheld from reads exactly like a literal. Store the real client secret as an app secret and point the setting at it. Web sign-in fails closed with that code before the request reaches Google. Native (iOS/Android) sign-in is not failed closed the same way: a PKCE exchange can prove possession of the auth code with the code verifier alone, so Primitive lets the request through rather than rejecting it on a value it cannot resolve. That is not the same as it still working — the setup above provisions a Google &quot;Web application&quot; client, and Google requires that client type&#39;s secret even alongside a code verifier, so the exchange fails at Google and surfaces as a generic <code>INVALID_TOKEN</code>.</p><p>Change these settings by editing <code>app.toml</code> and pushing it — there is no command that sets an app setting directly (see <a href="#toml-is-the-only-write-path">TOML Is the Only Write Path</a>):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.mode=invite-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span></span></code></pre></div><p><code>vars.toml</code> round-trips your app&#39;s <a href="./app-secrets.html#config-vars">config vars</a> the same way <code>app.toml</code> round-trips app settings — a flat table of non-secret key/value pairs, written by <code>config pull</code> and applied by <code>config push</code>.</p><p>Credentials never go in these files: config that needs an API key references it as <code>{{secrets.KEY}}</code>, with the value stored server-side. See <a href="./app-secrets.html">App Secrets</a>.</p><h2 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to “Email Templates”">​</a></h2><p>Primitive sends transactional email on your app&#39;s behalf — sign-in magic links and OTP codes, document and collection share notices, waitlist and invitation messages. Each kind has a built-in default, and you can override any of them with your own subject and body. Workflows can also register custom types to send app-specific mail such as order confirmations or receipts.</p><p>The built-in types are <code>magic-link</code>, <code>otp</code>, <code>document-share</code>, <code>document-share-deferred</code>, <code>collection-share</code>, <code>collection-share-deferred</code>, <code>waitlist-invite</code>, <code>waitlist-signup-notification</code>, <code>admin-invite</code>, <code>app-invite</code>, <code>access-request-created</code>, and <code>access-request-resolved</code>. An <a href="./workflows.html#email-send"><code>email.send</code></a> workflow step can send any of these, or a custom kebab-case type you register.</p><p>Each type exposes template variables — <code>{{magicLinkUrl}}</code> for <code>magic-link</code>, <code>{{otpCode}}</code> for <code>otp</code>, and so on — that Primitive substitutes at send time. A custom subject and/or HTML and text body overrides the built-in default; deleting the override restores it. Overrides live in the config directory as <code>email-templates/*.toml</code> and are authored and applied like any other configuration:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email-template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> magic-link</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # scaffold email-templates/magic-link.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... edit subject, html, text ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email-template/magic-link</span></span></code></pre></div><p>Delete the file and run <code>primitive config push --prune</code> to drop the override and go back to the built-in default. See <a href="./primitive-cli.html#email-templates">Email Templates</a> for the read commands — listing types and override status, viewing a type&#39;s current template and variables, and sending a test email.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to “Environments”">​</a></h2><p>A project usually targets more than one app — a development app for day-to-day coding, a production app for your customers. The CLI&#39;s named environments bind a server and app together so every command (including <code>config pull</code> and <code>config push</code>) knows which app it&#39;s talking to, and each environment gets its own isolated config directory. See <a href="./primitive-cli.html#project-configuration-and-environments">Project Configuration and Environments</a>.</p><h2 id="console-or-code" tabindex="-1">Console or Code? <a class="header-anchor" href="#console-or-code" aria-label="Permalink to “Console or Code?”">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Console</th><th>TOML + CLI</th></tr></thead><tbody><tr><td>Exploring and testing</td><td>Preferred — visual, interactive</td><td>Works but less convenient</td></tr><tr><td>Version-controlled config</td><td>—</td><td>Preferred</td></tr><tr><td>Quick one-off changes</td><td>Convenient</td><td>Convenient</td></tr><tr><td>AI agent automation</td><td>—</td><td>Preferred — agents speak CLI</td></tr><tr><td>CI/CD pipelines</td><td>—</td><td>Preferred — scriptable</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html">Primitive CLI</a></strong> — Full CLI reference, environments, and sync details</li><li><strong><a href="./admin-console.html">Admin Console</a></strong> — The interactive view of the same configuration</li><li><strong><a href="./workflows.html">Workflows</a></strong> — The most config-driven feature on the platform</li></ul>`,58)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
